const WORK_PAGE: &str = include_str!("../static/work.html");

fn unique_id(prefix: &str) -> String {
    let mut bytes = [0_u8; 8];
    getrandom::getrandom(&mut bytes).expect("the OS random source should be available");
    let suffix: String = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
    format!("{prefix}-{suffix}")
}

async fn enroll_repository(database_url: &str, tenant_id: &str, repository_id: &str, unique: &str) {
    let seed: [u8; 32] = Sha256::digest(format!("key-{unique}").as_bytes()).into();
    let signing_key = SigningKey::from_bytes(&seed);
    let public_key = signing_key.verifying_key().to_bytes();
    let request_id = format!("request-{unique}");
    let node_id = format!("node-{unique}");
    let fingerprint = public_key_fingerprint(&public_key);
    let submission = EnrollmentSubmission {
        request_id: request_id.clone(),
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id.clone(),
        display_name: "Work publication integration node".to_string(),
        public_key: public_key.to_vec(),
        public_key_fingerprint: fingerprint.clone(),
        requested_capabilities: vec!["synchronize".to_string()],
        created_at: "2026-01-01T00:00:00Z".to_string(),
        expires_at: "2030-01-01T00:00:00Z".to_string(),
    };
    let request = ActivationChallengeRequest {
        request_id,
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id,
        public_key_fingerprint: fingerprint,
    };
    let mut enrollment = EnrollmentStore::connect(database_url)
        .await
        .expect("connect enrollment store");
    enrollment
        .submit(&submission)
        .await
        .expect("submit enrollment");
    enrollment
        .approve(&EnrollmentApproval {
            request_id: submission.request_id.clone(),
            tenant_id: tenant_id.to_string(),
            repository_id: repository_id.to_string(),
            public_key_fingerprint: submission.public_key_fingerprint.clone(),
            approved_capabilities: submission.requested_capabilities.clone(),
            approved_by: "work-publication-administrator".to_string(),
        })
        .await
        .expect("approve enrollment");
    let nonce: [u8; 32] = Sha256::digest(format!("nonce-{unique}").as_bytes()).into();
    let challenge = enrollment
        .issue_challenge(&request, &nonce, SystemTime::now())
        .await
        .expect("issue enrollment challenge");
    let signature = signing_key.sign(&activation_challenge_bytes(
        &challenge.nonce,
        &request.request_id,
        &request.tenant_id,
        &request.repository_id,
        &request.proposed_node_id,
        &request.public_key_fingerprint,
    ));
    enrollment
        .activate(
            &EnrollmentActivation {
                request,
                nonce: challenge.nonce,
                signature: signature.to_bytes().to_vec(),
            },
            &format!("receipt-{unique}"),
            &format!("signing-key-{unique}"),
            SystemTime::now(),
        )
        .await
        .expect("activate enrollment");
}

async fn application(database_url: &str, tenant_id: &str) -> axum::Router {
    let work = Arc::new(
        WorkStore::connect(database_url)
            .await
            .expect("connect Work store"),
    );
    let fleet = Arc::new(
        FleetStore::connect(database_url)
            .await
            .expect("connect Fleet store"),
    );
    work_routes(WorkApiState::new(
        work,
        fleet,
        Arc::from(tenant_id.to_string()),
    ))
}

async fn body_json(response: axum::response::Response) -> Value {
    let body = to_bytes(response.into_body(), 1_048_576)
        .await
        .expect("read Bridge response body");
    serde_json::from_slice(&body).expect("parse Bridge JSON response")
}

#[tokio::test]
async fn work_list_distinguishes_claims_only_not_published_and_foreign_repositories() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("work-publication");
    let tenant_id = format!("tenant-{unique}");
    let claims_only_repository = format!("claims-only-{unique}");
    let unpublished_repository = format!("unpublished-{unique}");
    let foreign_tenant_id = format!("foreign-tenant-{unique}");
    let foreign_repository = format!("foreign-{unique}");
    enroll_repository(&database_url, &tenant_id, &claims_only_repository, &unique).await;
    enroll_repository(
        &database_url,
        &tenant_id,
        &unpublished_repository,
        &format!("unpublished-{unique}"),
    )
    .await;
    enroll_repository(
        &database_url,
        &foreign_tenant_id,
        &foreign_repository,
        &format!("foreign-{unique}"),
    )
    .await;

    let orphan_task_id = format!("claim-{unique}");
    let mut claims = ClaimStore::connect(&database_url)
        .await
        .expect("connect claim store");
    let claim = claims
        .delegate(
            &ClaimLeaseRequest {
                tenant_id: tenant_id.clone(),
                repository_id: claims_only_repository.clone(),
                task_id: orphan_task_id.clone(),
                owner_id: "owner-claims-only".to_string(),
                branch: "feat/industrial-work".to_string(),
                lease: Duration::from_secs(3_600),
                paths: vec!["crates/ackplane-bridge/static/work.html".to_string()],
                symbols: vec!["symbol:work-publication".to_string()],
            },
            SystemTime::now(),
        )
        .await
        .expect("create live orphan claim");
    assert_eq!(claim.outcome, ClaimLeaseOutcome::Granted);

    let app = application(&database_url, &tenant_id).await;
    let claims_only = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{claims_only_repository}/work?page=1&page_size=20"
                ))
                .body(Body::empty())
                .expect("build claims-only request"),
        )
        .await
        .expect("serve claims-only request");
    assert_eq!(claims_only.status(), StatusCode::OK);
    assert_eq!(
        body_json(claims_only).await,
        json!({
            "items": [],
            "total": 0,
            "page": 1,
            "page_size": 20,
            "publication": {
                "state": "claims_only",
                "claims_only_total": 1,
                "claims_only": [{
                    "task_id": orphan_task_id,
                    "owner_id": "owner-claims-only",
                    "branch": "feat/industrial-work",
                    "lease_expires_at_seconds": claim
                        .lease_expires_at
                        .duration_since(UNIX_EPOCH)
                        .expect("lease expiry is after the Unix epoch")
                        .as_secs(),
                    "declared_paths": ["crates/ackplane-bridge/static/work.html"],
                    "declared_symbols": ["symbol:work-publication"],
                }],
            },
        })
    );

    let unpublished = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{unpublished_repository}/work"
                ))
                .body(Body::empty())
                .expect("build unpublished request"),
        )
        .await
        .expect("serve unpublished request");
    assert_eq!(unpublished.status(), StatusCode::OK);
    assert_eq!(
        body_json(unpublished).await,
        json!({
            "items": [],
            "total": 0,
            "page": 1,
            "page_size": 20,
            "publication": {
                "state": "not_published",
                "claims_only_total": 0,
                "claims_only": [],
            },
        })
    );

    let foreign = app
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/repositories/{foreign_repository}/work"))
                .body(Body::empty())
                .expect("build foreign repository request"),
        )
        .await
        .expect("serve foreign repository request");
    assert_eq!(foreign.status(), StatusCode::NOT_FOUND);
}

#[test]
fn work_page_renders_publication_state_without_a_mutation_surface() {
    for required in [
        "id=\"publication\"",
        "renderPublication(data)",
        "claims_only_total",
        "Industrial Work has not been published",
        "Claims are published, but Work is not",
        "Claims awaiting an Industrial Work record",
        "class=\"table-scroll\"",
        ".table-scroll table { min-width:720px; }",
        "nav { flex-wrap:wrap; gap:10px; font-size:.78rem; }",
    ] {
        assert!(
            WORK_PAGE.contains(required),
            "work.html is missing {required}"
        );
    }
    assert_eq!(WORK_PAGE.matches("fetch(").count(), 1);
    for mutating_verb in ["\"POST\"", "\"PUT\"", "\"PATCH\"", "\"DELETE\""] {
        assert!(
            !WORK_PAGE.contains(mutating_verb),
            "work.html must not introduce a mutating request ({mutating_verb})"
        );
    }
}
